Let's write optimized kernel_gemver:

static
void kernel_gemver(int n, ...)
{
  int i, j;

#pragma scop

  const int TS = 32;

#pragma omp parallel default(none) shared(n, A, u1, v1, u2, v2, x, y, z, w, alpha, beta) private(i, j)
  {
    /* Phase 1: A = A + u1*v1^T + u2*v2^T */
    #pragma omp for schedule(static)
    for (int ii = 0; ii < _PB_N; ii += TS) {
      int i_max = (ii + TS < _PB_N) ? ii + TS : _PB_N;
      for (i = ii; i < i_max; i++) {
        DATA_TYPE u1i = u1[i];
        DATA_TYPE u2i = u2[i];
        #pragma omp simd
        for (j = 0; j < _PB_N; j++) {
          A[i][j] = A[i][j] + u1i * v1[j] + u2i * v2[j];
        }
      }
    }

    /* Phase 2+3 fused: x = x + beta * A^T * y + z */
    #pragma omp for schedule(static)
    for (int ii = 0; ii < _PB_N; ii += TS) {
      int i_max = (ii + TS < _PB_N) ? ii + TS : _PB_N;
      for (i = ii; i < i_max; i++) {
        DATA_TYPE sum = 0.0;
        for (j = 0; j < _PB_N; j++) {
          sum += beta * A[j][i] * y[j];
        }
        x[i] = x[i] + sum + z[i];
      }
    }

    /* Phase 4: w = w + alpha * A * x */
    #pragma omp for schedule(static)
    for (int ii = 0; ii < _PB_N; ii += TS) {
      int i_max = (ii + TS < _PB_N) ? ii + TS : _PB_N;
      for (i = ii; i < i_max; i++) {
        DATA_TYPE sum = 0.0;
        for (int jj = 0; jj < _PB_N; jj += TS) {
          int j_max = (jj + TS < _PB_N) ? jj + TS : _PB_N;
          for (j = jj; j < j_max; j++) {
            sum += alpha * A[i][j] * x[j];
          }
        }
        w[i] = w[i] + sum;
      }
    }
  }

#pragma endscop
}

